<?php
require_once __DIR__.'/config.php';
require_login();
$user=current_user();$formIdempotencyKey=fams_shared_idempotency_key();$me=(int)($user['id']??0);$isAdmin=user_is_admin();$popup=(($_GET['popup']??'')==='1'||($_POST['popup']??'')==='1');$id=(int)($_GET['record']??$_POST['record_id']??0);
$q=$pdo->prepare('SELECT * FROM aics_assistance_records WHERE id=?');$q->execute([$id]);$record=$q->fetch(PDO::FETCH_ASSOC);
$offices=$pdo->query("SELECT id,name FROM aics_offices WHERE is_active=1 AND parent_id=2 AND UPPER(TRIM(name)) NOT IN ('LPGMA','LPGMA OFFICE') ORDER BY sort_order,name")->fetchAll(PDO::FETCH_ASSOC);
if(!$record){http_response_code(404);exit('AICS record not found.');}
if(!fams_current_type_allows('AICS','submit_tickets')){http_response_code(403);exit('Your user type does not have permission to submit assistance tickets. Contact the LPGMA Site Administrator if this access is required.');}
if(function_exists('can_access_record_scope')&&!can_access_record_scope($record)&&!$isAdmin){http_response_code(403);exit('Access restricted: your account is assigned to a specific SWAD Office and may only view or request changes to entries assigned to that same office. This protects beneficiary privacy and preserves office-level accountability. If the entry belongs to your office but is assigned incorrectly, contact the LPGMA Site Administrator to review the office assignment; do not try to bypass the restriction.');}
$fields=['date_submission','client_first_name','client_middle_name','client_last_name','client_name_extension','barangay','municipality','province','contact_number','beneficiary_first_name','beneficiary_middle_name','beneficiary_last_name','beneficiary_name_extension','assistance_type','guarantee_amount','quotation','remarks','status','release_date'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$reason=trim((string)($_POST['reason']??''));if($reason===''){flash('error','Please explain why this record needs to be revised.');redirect('revision_ticket.php?popup=1&record='.$id);}
 $proposal=[];foreach($fields as $f){if(array_key_exists($f,$record))$proposal[$f]=trim((string)($_POST[$f]??''));}
 $requestedOffice=(int)($_POST['office_id']??0);if($requestedOffice<1){flash('error','Select the SWAD office where this entry should be assigned.');redirect('revision_ticket.php?popup=1&record='.$id);}
 $officeCheck=$pdo->prepare("SELECT COUNT(*) FROM aics_offices WHERE id=? AND is_active=1 AND parent_id=2 AND UPPER(TRIM(name)) NOT IN ('LPGMA','LPGMA OFFICE')");$officeCheck->execute([$requestedOffice]);if((int)$officeCheck->fetchColumn()!==1){flash('error','Select a valid active SWAD office.');redirect('revision_ticket.php?popup=1&record='.$id);}
 $proposal['office_id']=$requestedOffice;
 $proposal['_base_record_version']=(int)($record['record_version']??1);
 if($proposal['date_submission']===''||$proposal['date_submission']>date('Y-m-d')){flash('error','Date of submission must be valid and cannot be in the future.');redirect('revision_ticket.php?popup=1&record='.$id);}
 foreach(['client_first_name','client_last_name','beneficiary_first_name','beneficiary_last_name','barangay','municipality','province'] as $f){if(trim((string)$proposal[$f])===''){flash('error','Please complete all required name and address fields.');redirect('revision_ticket.php?popup=1&record='.$id);}}
 if(!in_array($proposal['assistance_type'],['MEDICAL','BURIAL','EDUCATIONAL','OTHER CASH','FOOD'],true)){flash('error','Select a valid assistance type.');redirect('revision_ticket.php?popup=1&record='.$id);}
 foreach(['guarantee_amount','quotation'] as $f){if($proposal[$f]!==''&&(!is_numeric($proposal[$f])||(float)$proposal[$f]<0)){flash('error','Amounts must be valid non-negative numbers.');redirect('revision_ticket.php?popup=1&record='.$id);}if($proposal[$f]!=='')$proposal[$f]=number_format((float)$proposal[$f],2,'.','');else $proposal[$f]=null;}
 if(!in_array($proposal['status'],['WAITING','RELEASED','CANCELLED'],true)){flash('error','Select a valid requested status.');redirect('revision_ticket.php?popup=1&record='.$id);}
 if($proposal['status']==='RELEASED'){if($proposal['release_date']===''||$proposal['release_date']<$proposal['date_submission']||$proposal['release_date']>date('Y-m-d')){flash('error','A valid release date is required for RELEASED status.');redirect('revision_ticket.php?popup=1&record='.$id);}}else $proposal['release_date']=null;
 foreach(['client_first_name','client_middle_name','client_last_name','client_name_extension','barangay','municipality','province','beneficiary_first_name','beneficiary_middle_name','beneficiary_last_name','beneficiary_name_extension','remarks'] as $f)$proposal[$f]=mb_strtoupper($proposal[$f]??'');
 $subject='Record Revision — '.$record['control_number'];$desc=$reason;
 if($requestedOffice!==(int)$record['office_id']){$officeName=$pdo->prepare('SELECT name FROM aics_offices WHERE id=?');$officeName->execute([$requestedOffice]);$desc .= "\nRequested SWAD office reassignment: ".(string)$officeName->fetchColumn().'.';}
 $ticketSequenceLock='fams:aics:ticket-sequence';$ticketLock=$pdo->prepare('SELECT GET_LOCK(?,8)');$ticketLock->execute([$ticketSequenceLock]);if((int)$ticketLock->fetchColumn()!==1){flash('error','The AICS ticket-number sequence is busy. Please retry.');redirect('revision_ticket.php?popup=1&record='.$id);}
 $ticketError=null;try{$created=fams_shared_idempotent_transaction($pdo,'aics.ticket.revision',(string)($_POST['idempotency_key']??''),$me,function(PDO $db) use ($id,$proposal,$subject,$desc,$me,$record): void {
  $no=aics_next_ticket_number($db);
  $lock=$db->prepare('SELECT * FROM aics_assistance_records WHERE id=? LIMIT 1 FOR UPDATE');$lock->execute([$id]);$current=$lock->fetch(PDO::FETCH_ASSOC);
  if(!$current || !can_access_record_scope($current))throw new RuntimeException('You are no longer authorized to submit a ticket for this record.');
  if((int)($current['record_version']??1)!==(int)($proposal['_base_record_version']??0))throw new RuntimeException('The record changed while this request was being prepared. Reload it and submit a new ticket.');
  $ins=$db->prepare("INSERT INTO aics_tickets(ticket_no,record_id,proposed_data,subject,category,description,status,created_by) VALUES(?,?,?,?,'RECORD REVISION',?,'OPEN',?)");$ins->execute([$no,$id,json_encode($proposal,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$subject,$desc,$me]);
  if(function_exists('log_action'))log_action($db,'CREATE_REVISION_TICKET','Submitted AICS revision ticket '.$no.' for '.$record['control_number'],$id);
 });}catch(Throwable $e){$ticketError=$e->getMessage();}finally{$release=$pdo->prepare('SELECT RELEASE_LOCK(?)');$release->execute([$ticketSequenceLock]);}
 if($ticketError!==null){flash('error',$ticketError);redirect('revision_ticket.php?popup=1&record='.$id);}
 if($popup){echo '<script>parent.postMessage({recordSaved:true,type:"fams-ticket-submitted"},"*");</script>';exit;}redirect('tickets.php');
}
$val=fn($f)=>e((string)($record[$f]??''));
if($popup)echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Submit Revision Ticket</title><link rel="stylesheet" href="assets/app.css?v='.e(APP_VERSION).'"></head><body class="fams-popup-page">';else require __DIR__.'/partials/header.php';
?>
<section class="panel form-panel"><div class="panel-heading"><div><span class="section-kicker">SUBMIT REVISION TICKET</span><h3>Record Revision — <?=e($record['control_number'])?></h3><span class="muted">This form mirrors the record editor. Changes below are proposals only and will not update the masterlist unless an administrator approves them.</span></div></div>
<div class="notice"><strong>Current status:</strong> <span class="status-badge <?=e(status_class($record['status']))?>"><?=e($record['status'])?></span><br><small>Current record values are prefilled for review. Submit a reason explaining the requested correction.</small></div>
<form method="post" class="record-form modern-editor-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="idempotency_key" value="<?=e($formIdempotencyKey)?>"><input type="hidden" name="popup" value="<?=$popup?'1':'0'?>"><input type="hidden" name="record_id" value="<?=$id?>">
<div class="form-section-title">Submission Details</div><div class="form-grid"><div><label>SWAD Office Assignment *</label><select name="office_id" required><?php foreach($offices as $o):?><option value="<?= (int)$o['id'] ?>" <?=((int)$record['office_id']===(int)$o['id'])?'selected':''?>><?=e($o['name'])?></option><?php endforeach;?></select><small class="muted">You may request reassignment to another active SWAD office. An administrator must approve the ticket before the assignment changes.</small></div><div><label>Date of Submission *</label><input type="date" name="date_submission" max="<?=e(date('Y-m-d'))?>" required value="<?=$val('date_submission')?>"></div><div><label>Assistance Type *</label><select name="assistance_type" required><?php foreach(['MEDICAL','BURIAL','EDUCATIONAL','OTHER CASH','FOOD'] as $a):?><option value="<?=$a?>" <?=$record['assistance_type']===$a?'selected':''?>><?=$a?></option><?php endforeach;?></select></div></div>
<div class="form-section-title">Client Details</div><div class="form-grid"><div><label>First Name *</label><input name="client_first_name" required value="<?=$val('client_first_name')?>"></div><div><label>Middle Name</label><input name="client_middle_name" value="<?=$val('client_middle_name')?>"></div><div><label>Last Name *</label><input name="client_last_name" required value="<?=$val('client_last_name')?>"></div><div><label>Name Extension</label><input name="client_name_extension" value="<?=$val('client_name_extension')?>"></div><div><label>Contact Number</label><input name="contact_number" value="<?=$val('contact_number')?>"></div></div>
<div class="form-section-title">Beneficiary Details</div><div class="form-grid"><div><label>First Name *</label><input name="beneficiary_first_name" required value="<?=$val('beneficiary_first_name')?>"></div><div><label>Middle Name</label><input name="beneficiary_middle_name" value="<?=$val('beneficiary_middle_name')?>"></div><div><label>Last Name *</label><input name="beneficiary_last_name" required value="<?=$val('beneficiary_last_name')?>"></div><div><label>Name Extension</label><input name="beneficiary_name_extension" value="<?=$val('beneficiary_name_extension')?>"></div></div>
<div class="form-section-title">Address</div><div class="form-grid"><div><label>Province *</label><input name="province" required value="<?=$val('province')?>"></div><div><label>Municipality / City *</label><input name="municipality" required value="<?=$val('municipality')?>"></div><div class="span-2"><label>Barangay *</label><input name="barangay" required value="<?=$val('barangay')?>"></div></div>
<div class="form-section-title">Financial Details</div><div class="form-grid"><div><label>Quotation Amount</label><input type="number" min="0" step="0.01" name="quotation" value="<?=$val('quotation')?>"></div><div><label>GL Amount</label><input type="number" min="0" step="0.01" name="guarantee_amount" value="<?=$val('guarantee_amount')?>"></div><div class="span-2"><label>Remarks</label><textarea name="remarks" rows="3"><?=$val('remarks')?></textarea></div></div>
<div class="form-section-title">Requested Status</div><div class="form-grid"><div><label>Status *</label><select name="status" id="revisionStatus" required><?php foreach(['WAITING','RELEASED','CANCELLED'] as $st):?><option value="<?=$st?>" <?=$record['status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select></div><div><label>Release Date</label><input type="date" name="release_date" id="revisionReleaseDate" value="<?=$val('release_date')?>" max="<?=e(date('Y-m-d'))?>"></div><div class="span-4"><label>Reason for Revision *</label><textarea name="reason" rows="4" required placeholder="Explain what needs to be corrected and why."></textarea></div></div>
<div class="form-actions"><button type="button" class="btn btn-secondary" onclick="parent.postMessage({type:'fams-close-popup'},'*')">Cancel</button><button type="submit" class="btn btn-primary">Submit for Admin Approval</button></div></form></section>
<script>(function(){const s=document.getElementById('revisionStatus'),d=document.getElementById('revisionReleaseDate');function sync(){d.required=s.value==='RELEASED';d.disabled=s.value!=='RELEASED';if(d.disabled)d.value='';}s.addEventListener('change',sync);sync();document.querySelector('form')?.addEventListener('submit',()=>parent.postMessage({type:'fams-popup-submitting'},'*'));})();</script>
